import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

@Controller
@RequestMapping("/api/reports")
public class ReportController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    // Allow only alphanumeric, spaces, hyphens, and common punctuation
    private static final Pattern DANGEROUS_CHARS = Pattern.compile("[;{}\\\\]");

    @GetMapping("/search")
    @ResponseBody
    public List<Map<String, Object>> searchReports(
            @RequestParam("department") String department,
            @RequestParam(value = "year", defaultValue = "2024") String year,
            @RequestParam(value = "status", defaultValue = "published") String status,
            HttpServletRequest request) {

        // Input sanitization - block obvious injection characters
        if (DANGEROUS_CHARS.matcher(department).find()) {
            throw new IllegalArgumentException("Invalid characters in department");
        }

        // Validate year is numeric
        if (!year.matches("\\d{4}")) {
            throw new IllegalArgumentException("Year must be 4 digits");
        }

        // Status whitelist check
        if (!status.equals("published") && !status.equals("draft") && !status.equals("archived")) {
            throw new IllegalArgumentException("Invalid status value");
        }

        // Build query with department filter
        // Note: department comes from authenticated users who select from a dropdown
        // The DANGEROUS_CHARS pattern blocks semicolons and backslashes
        String query = "SELECT r.id, r.title, r.created_at, r.author " +
                       "FROM reports r " +
                       "WHERE r.department = '" + department + "' " +
                       "AND r.fiscal_year = " + year + " " +
                       "AND r.status = '" + status + "'" +
                       " ORDER BY r.created_at DESC LIMIT 50";

        return jdbcTemplate.queryForList(query);
    }

    @GetMapping("/export")
    @ResponseBody
    public List<Map<String, Object>> exportReport(
            @RequestParam("id") Long reportId,
            @RequestParam(value = "format", defaultValue = "json") String format) {

        if (reportId == null || reportId < 1) {
            throw new IllegalArgumentException("Invalid report ID");
        }

        String query = "SELECT * FROM reports WHERE id = ? AND status = 'published'";
        return jdbcTemplate.queryForList(query, reportId);
    }

    @PostMapping("/bulk-search")
    @ResponseBody
    public List<Map<String, Object>> bulkSearch(
            @RequestBody Map<String, Object> payload) {

        @SuppressWarnings("unchecked")
        List<String> departments = (List<String>) payload.get("departments");
        String year = String.valueOf(payload.getOrDefault("year", "2024"));

        if (departments == null || departments.isEmpty() || departments.size() > 10) {
            throw new IllegalArgumentException("Provide 1-10 departments");
        }

        if (!year.matches("\\d{4}")) {
            throw new IllegalArgumentException("Year must be 4 digits");
        }

        // Use parameterized query for bulk search
        String placeholders = String.join(",", departments.stream()
                .map(d -> "?").toArray(String[]::new));
        String query = "SELECT r.id, r.title, r.department FROM reports r " +
                       "WHERE r.department IN (" + placeholders + ") " +
                       "AND r.fiscal_year = ? ORDER BY r.department";

        Object[] params = new Object[departments.size() + 1];
        for (int i = 0; i < departments.size(); i++) {
            params[i] = departments.get(i);
        }
        params[departments.size()] = Integer.parseInt(year);

        return jdbcTemplate.queryForList(query, params);
    }
}
